class LibraryMember {protected String id;protected int limit;private int borrowed;public LibraryMember(String i,int l){if(i==null||i.trim().length()<4)throw new IllegalArgumentException("Invalid ID");if(l<=0)throw new IllegalArgumentException("Limit must be positive");id=i;limit=l;}public void borrowBook(){if(borrowed>=limit)throw new IllegalStateException("Limit reached");borrowed++;}public int getBooksBorrowed(){return borrowed;}public void displayInfo(){System.out.print("General | Books: "+borrowed);}}
class StudentMember extends LibraryMember {private String course;public StudentMember(String i,int l,String c){super(i,l);course=c;}public String getCourse(){return course;}@Override public void displayInfo(){System.out.print("Student | Course: "+course+" | Books: "+getBooksBorrowed());}}
public class WeeklyCirculationReportMain {public static String batchPrint(LibraryMember[] ms){StringBuilder b=new StringBuilder();for(LibraryMember m:ms){if(b.length()>0)b.append(" | ");if(m instanceof StudentMember){StudentMember s=(StudentMember)m;b.append("Student | Course: ").append(s.getCourse()).append(" | Books: ").append(s.getBooksBorrowed()).append(" [Course via downcast: ").append(s.getCourse()).append("]");}else b.append("General | Books: ").append(m.getBooksBorrowed());}return b.toString();}public static void main(String[] a){System.out.println(batchPrint(new LibraryMember[]{new LibraryMember("LB5",3),new StudentMember("STU6",3,"ECE")}));}}
